      "title": "Elimination vs. Endemic Persistence",
      "goal": "Explore how keeping the reproduction number below one can lead to TB elimination.",
      "control": {
        "parameter": "beta",
        "label": "Contact Rate",
        "lowEnd": "0.02",
        "highEnd": "0.08"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if the contact rate is doubled?",
        "parameter": "beta",
        "value": 0.1
      },
      "difference": {
