        "summary": "peak",
        "at": null,
        "time": 36,
        "relation": "higher",
        "by": 100
      },
      "effect": "Doubling the contact rate raises the peak number of infectious individuals by more than 100.",
      "prediction": {
        "prompt": "Predict the change in peak infectious when beta is doubled.",
