    {
      "kind": "background",
      "finding": 1,
      "title": "Basic Reproduction Number Threshold",
      "goal": "Understand the significance of the estimated R0 of 2.67.",
      "control": {
        "parameter": "delta",
        "label": "Treatment Rate",
        "lowEnd": "0.2",
        "highEnd": "1.0"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if the treatment rate is halved?",
        "parameter": "delta",
        "value": 0.335
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 36,
        "relation": "higher",
        "by": 80
      },
      "effect": "Halving the treatment rate increases the peak infectious population by more than 80.",
      "prediction": {
        "prompt": "Predict the effect of halving delta on the infectious peak.",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Threshold Finding",
        "quote": "We obtained $R_0 = 2.67$ for the estimated model parameters, which are greater than one, indicating that the tuberculosis is continuously multiplying."
      },
      "carryForward": "Examine how treatment efficacy impacts TB dynamics."
    },
    {
      "kind": "idea",
      "finding": 2,
      "title": "Impact of Treatment Rate on TB Cases",
      "goal": "See how increasing the treatment rate reduces TB cases.",
      "control": {
        "parameter": "delta",
        "label": "Treatment Rate",
        "lowEnd": "0.2",
        "highEnd": "1.34"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if the treatment rate is doubled?",
        "parameter": "delta",
        "value": 1.34
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 36,
        "relation": "lower",
        "by": 70
      },
      "effect": "Doubling the treatment rate lowers the peak number of infectious individuals by more than 70.",
      "prediction": {
        "prompt": "Predict the change in infectious peak when delta is doubled.",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Treatment Effect",
        "quote": "The result revealed that the infectious population decreases as the treatment rate of infected individuals increases; in the long run, this may lead to the eradication of the disease from the community."
      },
      "carryForward": "Investigate the role of treatment speed in controlling TB outbreaks."
    },
    {
      "kind": "method",
      "finding": 3,
      "title": "Key Drivers of TB Transmission",
      "goal": "Identify which parameters most strongly drive TB spread.",
      "control": {
        "parameter": "gamma",
        "label": "Progression Rate (Exposed to Infectious)",
        "lowEnd": "0.1",
        "highEnd": "0.96"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if the progression rate is doubled?",
        "parameter": "gamma",
        "value": 0.96
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 36,
        "relation": "higher",
        "by": 90
      },
      "effect": "Doubling the progression rate increases the peak infectious population by more than 90.",
      "prediction": {
        "prompt": "Predict the effect of doubling gamma on the infectious peak.",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Sensitivity Analysis",
        "quote": "contact rate ($beta$), recruitment rate ($Lambda$), the loss of protection for the vaccination rate ($theta$), and rate of progression from the exposed class to the infectious class ($gamma$) were the most important factors."
      },
      "carryForward": "Explore how changes in progression from latent to active infection affect TB dynamics."
    },
    {
      "kind": "evaluation",
      "finding": 4,
      "title": "Reducing TB Burden",
