      "control": {
        "parameter": "pi",
        "label": "Vaccination Rate",
        "lowEnd": "0.05",
        "highEnd": "0.2"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if the vaccination rate is doubled?",
        "parameter": "pi",
        "value": 0.2
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 36,
        "relation": "lower",
        "by": 50
      },
      "effect": "Doubling the vaccination rate reduces the peak number of infectious individuals by more than 50.",
      "prediction": {
        "prompt": "Predict the change in infectious peak when pi is doubled.",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Burden Reduction",
        "quote": "Parameters with negative sensitivity indices ($mu$, $pi$, $delta$, $tau$) have the effect of lowering the community's TB burden if their values increases"
      },
      "carryForward": "Assess how enhanced vaccination and treatment strategies impact TB prevalence."
    }
  ],
  "limits": [
    "Each level must run for no more than 20 seconds at 4× speed.",
    "The control parameter must be a rate (not a starting value).",
    "The What‑if must change one parameter or starting value discussed in the paper.",
    "The measured difference must be clear on a chart and affect at least 3 figures in the visual town."
  ]
}
